import { DEBOUNCE_DELAY, SCAN_EVENTS } from "../constants.js";
export function createScanner(onScan) {
  let debounceTimer = null;
  let eventListenersAttached = false;
  function debouncedScan() {
    if (debounceTimer) {
      clearTimeout(debounceTimer);
    }
    debounceTimer = setTimeout(() => {
      onScan();
    }, DEBOUNCE_DELAY);
  }
  function enable() {
    if (eventListenersAttached)
      return;
    SCAN_EVENTS.forEach((event) => {
      document.addEventListener(event, debouncedScan, true);
    });
    eventListenersAttached = true;
  }
  function disable() {
    if (!eventListenersAttached)
      return;
    SCAN_EVENTS.forEach((event) => {
      document.removeEventListener(event, debouncedScan, true);
    });
    eventListenersAttached = false;
    if (debounceTimer) {
      clearTimeout(debounceTimer);
      debounceTimer = null;
    }
  }
  function isEnabled() {
    return eventListenersAttached;
  }
  return {
    enable,
    disable,
    isEnabled
  };
}
